import{_ as e,o as i,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"UC 04 — Content & Task Workflow (UC-42 → UC-73)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/04-content-task-workflow.md","filePath":"ba/use-cases/04-content-task-workflow.md"}'),s={name:"ba/use-cases/04-content-task-workflow.md"};function o(l,t,n,d,c,g){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="uc-04-—-content-task-workflow-uc-42-→-uc-73" tabindex="-1">UC 04 — Content &amp; Task Workflow (UC-42 → UC-73) <a class="header-anchor" href="#uc-04-—-content-task-workflow-uc-42-→-uc-73" aria-label="Permalink to &quot;UC 04 — Content &amp; Task Workflow (UC-42 → UC-73)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../05-content-task-workflow.html">05-content-task-workflow.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code> &gt; <strong>Nguồn gốc Task trong backlog (3 nguồn):</strong> Media Campaign approve, Content Request accepted, Manager thêm thủ công.</p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-42</td><td>Define Task Detail</td><td>MANAGER</td><td>3.6.1</td></tr><tr><td>UC-43</td><td>Assign Task to Creator</td><td>MANAGER</td><td>3.6.2</td></tr><tr><td>UC-44</td><td>Comment on Task</td><td>CREATOR/CLIENT/MANAGER</td><td>3.6.3</td></tr><tr><td>UC-45</td><td>View Tasks in Multiple Views</td><td>CREATOR/CLIENT/MANAGER</td><td>3.6.4–3.6.7</td></tr><tr><td>UC-46</td><td>Filter &amp; Search Tasks</td><td>CREATOR/CLIENT/MANAGER</td><td>3.6.8</td></tr><tr><td>UC-47</td><td>Task Approval Sequence</td><td>CREATOR/CLIENT/MANAGER</td><td>3.6.9</td></tr><tr><td>UC-48</td><td>Write Content</td><td>CREATOR</td><td>3.6.10</td></tr><tr><td>UC-49</td><td>View Content Version History</td><td>CREATOR</td><td>3.6.35</td></tr><tr><td>UC-50</td><td>View Material Repository</td><td>CREATOR/CLIENT</td><td>3.6.11</td></tr><tr><td>UC-51</td><td>Add Material to Repository</td><td>CREATOR/CLIENT</td><td>3.6.12</td></tr><tr><td>UC-52</td><td>Update Material in Repository</td><td>CREATOR/CLIENT</td><td>3.6.13</td></tr><tr><td>UC-53</td><td>Delete Material from Repository</td><td>CREATOR/CLIENT</td><td>3.6.14</td></tr><tr><td>UC-54</td><td>Apply Watermark to Material</td><td>CREATOR</td><td>3.6.15</td></tr><tr><td>UC-55</td><td>Download Material</td><td>CREATOR/CLIENT</td><td>3.6.16</td></tr><tr><td>UC-56</td><td>Apply Hashtag to Post</td><td>CREATOR</td><td>3.6.17</td></tr><tr><td>UC-57</td><td>View Hashtag Collection</td><td>CREATOR/CLIENT</td><td>3.6.18</td></tr><tr><td>UC-58</td><td>Add Hashtag to Collection</td><td>CREATOR</td><td>3.6.19</td></tr><tr><td>UC-59</td><td>Update Hashtag Collection</td><td>CREATOR</td><td>3.6.20</td></tr><tr><td>UC-60</td><td>Delete Hashtag from Collection</td><td>CREATOR</td><td>3.6.21</td></tr><tr><td>UC-61</td><td>Write Livestream Idea</td><td>MANAGER/CREATOR</td><td>3.6.22</td></tr><tr><td>UC-62</td><td>Write Livestream Script</td><td>CREATOR</td><td>3.6.23</td></tr><tr><td>UC-63</td><td>Track Livestream Status</td><td>MANAGER</td><td>3.6.24</td></tr><tr><td>UC-64</td><td>Create Survey</td><td>CREATOR/MANAGER</td><td>3.6.25</td></tr><tr><td>UC-65</td><td>View Survey Analysis</td><td>CREATOR/MANAGER</td><td>3.6.26</td></tr><tr><td>UC-66</td><td>Generate Meeting Link</td><td>CREATOR</td><td>3.6.27</td></tr><tr><td>UC-67</td><td>View Email Template</td><td>MANAGER/CREATOR</td><td>3.6.28</td></tr><tr><td>UC-68</td><td>Create Email Template</td><td>MANAGER/CREATOR</td><td>3.6.29</td></tr><tr><td>UC-69</td><td>Update Email Template</td><td>MANAGER/CREATOR</td><td>3.6.30</td></tr><tr><td>UC-70</td><td>Delete Email Template</td><td>MANAGER/CREATOR</td><td>3.6.31</td></tr><tr><td>UC-71</td><td>Send Email via Template</td><td>MANAGER/CREATOR</td><td>3.6.32</td></tr><tr><td>UC-72</td><td>Check Content Compliance</td><td>CREATOR/CLIENT</td><td>3.6.33</td></tr><tr><td>UC-73</td><td>Check Copyright Infringement</td><td>CREATOR/CLIENT</td><td>3.6.34</td></tr></tbody></table><hr><h2 id="uc-42-—-define-task-detail" tabindex="-1">UC-42 — Define Task Detail <a class="header-anchor" href="#uc-42-—-define-task-detail" aria-label="Permalink to &quot;UC-42 — Define Task Detail&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER</li><li><strong>Description:</strong> Add full details (due date, detailed requirements) to a task pulled from the backlog.</li><li><strong>Precondition:</strong> Task exists in backlog with only name/title/output requirement (no assignee/detail yet).</li><li><strong>Main Flow:</strong><ol><li>MANAGER opens a backlog Task.</li><li>Fills in assignee-pending detail fields: due date, detailed requirements, and type-specific fields (Post/Livestream/Survey).</li><li>System saves the detailed Task, ready for assignment (UC-43).</li></ol></li></ul><h2 id="uc-43-—-assign-task-to-creator" tabindex="-1">UC-43 — Assign Task to Creator <a class="header-anchor" href="#uc-43-—-assign-task-to-creator" aria-label="Permalink to &quot;UC-43 — Assign Task to Creator&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER</li><li><strong>Description:</strong> Assign a defined task to the Creator responsible for it.</li><li><strong>Precondition:</strong> Task detail defined (UC-42).</li><li><strong>Main Flow:</strong><ol><li>MANAGER selects a Creator to execute the task.</li><li>Requires a nonblank brief and valid dueDate; no QC assignment in the current workflow. Task remains TODO; Manager edits/reassignment are locked after the Creator first starts.</li><li>System notifies the assigned Creator.</li></ol></li></ul><h2 id="uc-44-—-comment-on-task" tabindex="-1">UC-44 — Comment on Task <a class="header-anchor" href="#uc-44-—-comment-on-task" aria-label="Permalink to &quot;UC-44 — Comment on Task&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT/MANAGER</li><li><strong>Description:</strong> Add comments and edit requests on a task.</li><li><strong>Precondition:</strong> Task exists and actor has access (assignee, workspace member, or client with visibility).</li><li><strong>Main Flow:</strong><ol><li>Actor writes a comment or edit request on the Task thread.</li><li>System notifies relevant participants (assignee/manager/client).</li></ol></li></ul><h2 id="uc-45-—-view-tasks-in-multiple-views" tabindex="-1">UC-45 — View Tasks in Multiple Views <a class="header-anchor" href="#uc-45-—-view-tasks-in-multiple-views" aria-label="Permalink to &quot;UC-45 — View Tasks in Multiple Views&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT/MANAGER</li><li><strong>Description:</strong> View the task list as List, Calendar, Gantt Timeline, or Kanban Board.</li><li><strong>Precondition:</strong> User has access to the Workspace.</li><li><strong>Main Flow:</strong><ol><li>User selects a view mode: List (Jira-style), Calendar (drag-drop, Google Calendar-style), Gantt Timeline (waterfall), or Kanban Board (drag between status columns).</li><li>System renders tasks accordingly, live-synced across all views.</li></ol></li></ul><h2 id="uc-46-—-filter-search-tasks" tabindex="-1">UC-46 — Filter &amp; Search Tasks <a class="header-anchor" href="#uc-46-—-filter-search-tasks" aria-label="Permalink to &quot;UC-46 — Filter &amp; Search Tasks&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT/MANAGER</li><li><strong>Description:</strong> Filter, sort, and search tasks by any data field across all view types.</li><li><strong>Precondition:</strong> User is viewing a Task view (UC-45).</li><li><strong>Main Flow:</strong><ol><li>User applies filter/sort/search criteria (assignee, status, date, type, etc.).</li><li>System narrows displayed tasks across the current view.</li></ol></li></ul><h2 id="uc-47-—-task-approval-sequence" tabindex="-1">UC-47 — Task Approval Sequence <a class="header-anchor" href="#uc-47-—-task-approval-sequence" aria-label="Permalink to &quot;UC-47 — Task Approval Sequence&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT/MANAGER</li><li><strong>Current BA:</strong> Confirmed 2026-10-18; <a href="./../../feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.html">FR 3.6.9 v3</a> supersedes the previous QC/intermediate-state flow. Backend, POST integration and UI have isolated verification; rollout remains disabled pending Atlas preflight/APPLY, publisher coordination and SQL/inbox/Gateway end-to-end testing.</li><li><strong>Description:</strong> Assigned Creator submits → Manager → one active Client if required; no QC. Integrate POST from /editor first, one current content record, no review snapshots.</li><li><strong>Precondition:</strong> Active assignee explicitly started the Task, Task is IN_PROGRESS, a valid linked Post exists, and required reviewers are available. Missing active Client when required blocks submission and prompts the Manager to add one.</li><li><strong>Main Flow:</strong><ol><li>Creator saves the linked Post and submits: IN_REVIEW/MANAGER; content is locked server-side.</li><li>Manager reviews and approves/rejects.</li><li>Any one active Client reviews at CLIENT step only if requiresClientApproval; first valid decision wins.</li><li>Final approval sets FINISHED, clears reviewStep; publishing remains a separate action.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Reject requires a reason → IN_PROGRESS. Edit the same Post, resubmit in a new round from Manager. Retain past decisions; no old-content snapshot/diff is available.</li><li>A2. Assigned Creator may withdraw only before the Manager decides; IN_PROGRESS, next submit starts a new round. No withdrawal while waiting for Client.</li><li>A3. All Clients leave during CLIENT review → remain waiting, no automatic skip; Manager adds a Client through the existing membership feature.</li><li>A4. Cancellation closes the review; stale/duplicate/wrong-step decisions cannot mutate a terminal Task or create duplicate history. Manager brief/reassignment stays locked after first start.</li></ul></li></ul><h2 id="uc-48-—-write-content" tabindex="-1">UC-48 — Write Content <a class="header-anchor" href="#uc-48-—-write-content" aria-label="Permalink to &quot;UC-48 — Write Content&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Write text content with automatic font conversion for publishing.</li><li><strong>Precondition:</strong> Task assigned to Creator (Post-type task).</li><li><strong>Main Flow:</strong><ol><li>CREATOR writes content in a vector-text editor (Google Docs-style).</li><li>System auto-converts font encoding to the platform-correct standard on publish (removes manual Unikey/Yantext conversion step).</li></ol></li><li><strong>Postcondition:</strong> Content saved with a new version snapshot (see UC-49).</li></ul><h2 id="uc-49-—-view-content-version-history" tabindex="-1">UC-49 — View Content Version History <a class="header-anchor" href="#uc-49-—-view-content-version-history" aria-label="Permalink to &quot;UC-49 — View Content Version History&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> View and restore previous versions of written content.</li><li><strong>Precondition:</strong> Content has at least one prior saved version.</li><li><strong>Main Flow:</strong><ol><li>CREATOR opens Version History for a content item.</li><li>System lists versions with editor + timestamp.</li><li>CREATOR selects a version to restore.</li></ol></li></ul><h2 id="uc-50-—-view-material-repository" tabindex="-1">UC-50 — View Material Repository <a class="header-anchor" href="#uc-50-—-view-material-repository" aria-label="Permalink to &quot;UC-50 — View Material Repository&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> View the repository of materials (raw/retouched photos, client-provided brand assets).</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>User opens Material Repository.</li><li>System lists materials tagged raw/retouched, plus Client-provided Brand Assets (separate category from Creator-produced Material).</li></ol></li><li><strong>Note:</strong> Raw (unprocessed) material shows a warning if selected for publishing.</li></ul><h2 id="uc-51-—-add-material-to-repository" tabindex="-1">UC-51 — Add Material to Repository <a class="header-anchor" href="#uc-51-—-add-material-to-repository" aria-label="Permalink to &quot;UC-51 — Add Material to Repository&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> Upload a new material into the repository.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>User uploads a file, tags it raw/retouched (or Brand Asset if Client-provided).</li><li>System stores the material in the repository.</li></ol></li></ul><h2 id="uc-52-—-update-material-in-repository" tabindex="-1">UC-52 — Update Material in Repository <a class="header-anchor" href="#uc-52-—-update-material-in-repository" aria-label="Permalink to &quot;UC-52 — Update Material in Repository&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> Update an existing material&#39;s information in the repository.</li><li><strong>Precondition:</strong> Material exists.</li><li><strong>Main Flow:</strong><ol><li>User edits material metadata (tags, description, processing status).</li><li>System persists changes.</li></ol></li></ul><h2 id="uc-53-—-delete-material-from-repository" tabindex="-1">UC-53 — Delete Material from Repository <a class="header-anchor" href="#uc-53-—-delete-material-from-repository" aria-label="Permalink to &quot;UC-53 — Delete Material from Repository&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> Remove a material from the repository.</li><li><strong>Precondition:</strong> Material exists.</li><li><strong>Main Flow:</strong><ol><li>User selects Delete, confirms.</li><li>System removes the material from the repository.</li></ol></li></ul><h2 id="uc-54-—-apply-watermark-to-material" tabindex="-1">UC-54 — Apply Watermark to Material <a class="header-anchor" href="#uc-54-—-apply-watermark-to-material" aria-label="Permalink to &quot;UC-54 — Apply Watermark to Material&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Apply a brand watermark onto a material.</li><li><strong>Precondition:</strong> Material has been retouched/edited; Client-provided logo available.</li><li><strong>Main Flow:</strong><ol><li>CREATOR selects a material and the Client&#39;s brand logo.</li><li>System applies watermark overlay (img2go-style tool), saves the watermarked output.</li></ol></li></ul><h2 id="uc-55-—-download-material" tabindex="-1">UC-55 — Download Material <a class="header-anchor" href="#uc-55-—-download-material" aria-label="Permalink to &quot;UC-55 — Download Material&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> Download a material from the repository to a local device.</li><li><strong>Precondition:</strong> Material exists and user has access.</li><li><strong>Main Flow:</strong><ol><li>User selects Download on a material.</li><li>System streams the file to the user&#39;s device.</li></ol></li><li><strong>Note:</strong> All Workspace roles (Creator/Client/Manager) can perform this action.</li></ul><h2 id="uc-56-—-apply-hashtag-to-post" tabindex="-1">UC-56 — Apply Hashtag to Post <a class="header-anchor" href="#uc-56-—-apply-hashtag-to-post" aria-label="Permalink to &quot;UC-56 — Apply Hashtag to Post&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Attach one or more hashtags to a post or campaign.</li><li><strong>Precondition:</strong> Post/campaign draft exists.</li><li><strong>Main Flow:</strong><ol><li>CREATOR selects hashtags from the Workspace Hashtag Collection (or types new ones).</li><li>System attaches hashtags to the post/campaign.</li></ol></li></ul><h2 id="uc-57-—-view-hashtag-collection" tabindex="-1">UC-57 — View Hashtag Collection <a class="header-anchor" href="#uc-57-—-view-hashtag-collection" aria-label="Permalink to &quot;UC-57 — View Hashtag Collection&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> View the Workspace&#39;s saved hashtag collection.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>User opens Hashtag Collection.</li><li>System lists saved hashtags, including AI-recommended suggestions.</li></ol></li></ul><h2 id="uc-58-—-add-hashtag-to-collection" tabindex="-1">UC-58 — Add Hashtag to Collection <a class="header-anchor" href="#uc-58-—-add-hashtag-to-collection" aria-label="Permalink to &quot;UC-58 — Add Hashtag to Collection&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Add a new hashtag to the Workspace&#39;s hashtag collection.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>CREATOR enters a new hashtag, tags its intended usage/category.</li><li>System stores it in the collection.</li></ol></li><li><strong>Note:</strong> Client-added hashtags are event-specific and mandatory-use per FR 3.6.18; Creator additions are free-form.</li></ul><h2 id="uc-59-—-update-hashtag-collection" tabindex="-1">UC-59 — Update Hashtag Collection <a class="header-anchor" href="#uc-59-—-update-hashtag-collection" aria-label="Permalink to &quot;UC-59 — Update Hashtag Collection&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Update an existing hashtag in the collection.</li><li><strong>Precondition:</strong> Hashtag exists in the collection.</li><li><strong>Main Flow:</strong><ol><li>CREATOR edits hashtag text/category.</li><li>System persists changes.</li></ol></li></ul><h2 id="uc-60-—-delete-hashtag-from-collection" tabindex="-1">UC-60 — Delete Hashtag from Collection <a class="header-anchor" href="#uc-60-—-delete-hashtag-from-collection" aria-label="Permalink to &quot;UC-60 — Delete Hashtag from Collection&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Soft-delete a hashtag from the collection.</li><li><strong>Precondition:</strong> Hashtag exists.</li><li><strong>Main Flow:</strong><ol><li>CREATOR selects Delete, confirms.</li><li>System soft-deletes the hashtag — already-applied usages on old posts remain unaffected.</li></ol></li></ul><h2 id="uc-61-—-write-livestream-idea" tabindex="-1">UC-61 — Write Livestream Idea <a class="header-anchor" href="#uc-61-—-write-livestream-idea" aria-label="Permalink to &quot;UC-61 — Write Livestream Idea&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER/CREATOR</li><li><strong>Description:</strong> Fill in the initial idea/concept for a livestream session.</li><li><strong>Precondition:</strong> Livestream-type Task assigned.</li><li><strong>Main Flow:</strong><ol><li>MANAGER/CREATOR fills in idea, target goal for the livestream.</li><li>System saves the idea as the livestream session&#39;s initial state.</li></ol></li></ul><h2 id="uc-62-—-write-livestream-script" tabindex="-1">UC-62 — Write Livestream Script <a class="header-anchor" href="#uc-62-—-write-livestream-script" aria-label="Permalink to &quot;UC-62 — Write Livestream Script&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Write the full script for a livestream session.</li><li><strong>Precondition:</strong> Livestream idea exists (UC-61).</li><li><strong>Main Flow:</strong><ol><li>CREATOR writes the full script (talking points, timing, risk considerations, shot list).</li><li>System saves the script tied to the livestream session.</li></ol></li></ul><h2 id="uc-63-—-track-livestream-status" tabindex="-1">UC-63 — Track Livestream Status <a class="header-anchor" href="#uc-63-—-track-livestream-status" aria-label="Permalink to &quot;UC-63 — Track Livestream Status&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER</li><li><strong>Description:</strong> Track the progress/status of a livestream session.</li><li><strong>Precondition:</strong> Livestream session exists with script ready.</li><li><strong>Main Flow:</strong><ol><li>MANAGER opens the livestream tracker.</li><li>System displays current state: <code>PRE_LIVE → LIVE → POST_LIVE → DONE/CANCEL</code>.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Session cancelled at any pre-completion state → moves to <code>CANCEL</code>.</li></ul></li></ul><h2 id="uc-64-—-create-survey" tabindex="-1">UC-64 — Create Survey <a class="header-anchor" href="#uc-64-—-create-survey" aria-label="Permalink to &quot;UC-64 — Create Survey&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/MANAGER</li><li><strong>Description:</strong> Create a survey for a workshop or campaign.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>User builds survey questions with time slots (form-builder style), previews the form.</li><li>System saves and publishes the survey.</li></ol></li></ul><h2 id="uc-65-—-view-survey-analysis" tabindex="-1">UC-65 — View Survey Analysis <a class="header-anchor" href="#uc-65-—-view-survey-analysis" aria-label="Permalink to &quot;UC-65 — View Survey Analysis&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/MANAGER</li><li><strong>Description:</strong> View the overall analysis of survey results.</li><li><strong>Precondition:</strong> Survey has received responses.</li><li><strong>Main Flow:</strong><ol><li>User opens Survey Analysis.</li><li>System displays aggregated results/statistics.</li></ol></li></ul><h2 id="uc-66-—-generate-meeting-link" tabindex="-1">UC-66 — Generate Meeting Link <a class="header-anchor" href="#uc-66-—-generate-meeting-link" aria-label="Permalink to &quot;UC-66 — Generate Meeting Link&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Automatically generate a Google Meet link for a meeting.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>CREATOR requests a meeting link for a scheduled session.</li><li>System calls Google Meet API, returns a generated link.</li></ol></li></ul><h2 id="uc-67-—-view-email-template" tabindex="-1">UC-67 — View Email Template <a class="header-anchor" href="#uc-67-—-view-email-template" aria-label="Permalink to &quot;UC-67 — View Email Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER/CREATOR</li><li><strong>Description:</strong> View the list of saved email templates.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>User opens Email Template list.</li><li>System displays saved templates.</li></ol></li><li><strong>Note:</strong> Role assignment for this FR group is an <strong>[OPEN QUESTION]</strong> in the source CSV — not finalized.</li></ul><h2 id="uc-68-—-create-email-template" tabindex="-1">UC-68 — Create Email Template <a class="header-anchor" href="#uc-68-—-create-email-template" aria-label="Permalink to &quot;UC-68 — Create Email Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER/CREATOR</li><li><strong>Description:</strong> Create a new email template.</li><li><strong>Precondition:</strong> User has Workspace access.</li><li><strong>Main Flow:</strong><ol><li>User composes a new template (subject, body, placeholders).</li><li>System saves the template.</li></ol></li></ul><h2 id="uc-69-—-update-email-template" tabindex="-1">UC-69 — Update Email Template <a class="header-anchor" href="#uc-69-—-update-email-template" aria-label="Permalink to &quot;UC-69 — Update Email Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER/CREATOR</li><li><strong>Description:</strong> Update an existing email template.</li><li><strong>Precondition:</strong> Template exists.</li><li><strong>Main Flow:</strong><ol><li>User edits template content.</li><li>System persists changes.</li></ol></li></ul><h2 id="uc-70-—-delete-email-template" tabindex="-1">UC-70 — Delete Email Template <a class="header-anchor" href="#uc-70-—-delete-email-template" aria-label="Permalink to &quot;UC-70 — Delete Email Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER/CREATOR</li><li><strong>Description:</strong> Delete an existing email template.</li><li><strong>Precondition:</strong> Template exists.</li><li><strong>Main Flow:</strong><ol><li>User selects Delete, confirms.</li><li>System removes the template.</li></ol></li></ul><h2 id="uc-71-—-send-email-via-template" tabindex="-1">UC-71 — Send Email via Template <a class="header-anchor" href="#uc-71-—-send-email-via-template" aria-label="Permalink to &quot;UC-71 — Send Email via Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER/CREATOR</li><li><strong>Description:</strong> Send an email to a recipient using a selected template.</li><li><strong>Precondition:</strong> Template exists.</li><li><strong>Main Flow:</strong><ol><li>User selects a template, fills recipient + placeholder values.</li><li>System sends the email.</li></ol></li></ul><h2 id="uc-72-—-check-content-compliance" tabindex="-1">UC-72 — Check Content Compliance <a class="header-anchor" href="#uc-72-—-check-content-compliance" aria-label="Permalink to &quot;UC-72 — Check Content Compliance&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> Check content for plagiarism, violence, or explicit imagery via a third-party API.</li><li><strong>Precondition:</strong> Content draft ready for review.</li><li><strong>Main Flow:</strong><ol><li>User triggers compliance check.</li><li>System calls third-party moderation API, returns a flagged-terms/segments analysis.</li><li>User reviews flagged items and revises before publishing (avoids platform policy violations / trending suppression).</li></ol></li></ul><h2 id="uc-73-—-check-copyright-infringement" tabindex="-1">UC-73 — Check Copyright Infringement <a class="header-anchor" href="#uc-73-—-check-copyright-infringement" aria-label="Permalink to &quot;UC-73 — Check Copyright Infringement&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR/CLIENT</li><li><strong>Description:</strong> Check images/brand assets for copyright infringement via a third-party API.</li><li><strong>Precondition:</strong> Image/brand asset ready for review.</li><li><strong>Main Flow:</strong><ol><li>User triggers copyright check on an image/asset.</li><li>System calls third-party API, returns infringement analysis.</li></ol></li><li><strong>Note:</strong> Technical detail <strong>[OPEN QUESTION]</strong> — source notes &quot;needs clarification&quot;, not yet fully specified.</li></ul>',69)])])}const m=e(s,[["render",o]]);export{u as __pageData,m as default};
